Translate("ruRU", "silverpine-forest", {
	title = "Серебряный бор",
	aliases = { "Серебряный бор" },
	sections = {
		{
			title = "Обзор",
			text = [=[Серебряный бор тянется на юг от {link:tirisfal-glades}Тирисфальских лесов{/link} до великой стены королевства {link:gilneas}Гилнеас{/link}. Темные сосны теснятся на его холмах, а на востоке его берега спускаются к серой воде {red:lordamere-lake}озера Лордамер{/red}. Некогда это был тихий край ферм, садов и мельниц. Теперь это земля мертвых и проклятых. {link:forsaken}Отрекшиеся{/link} держат его дороги из Гробницы, {link:scourge}Плеть{/link} держит островную крепость на озере, а в холмах воют люди-волки безумного архимага из {link:dalaran}Даларана{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не называет год, когда первые люди поселились в Серебряном бору, и не говорит, какой лорд первым объявил его своим. Его жители возделывали долины, ухаживали за садами и работали на мельницах. Над деревушкой П{link:ogres}огр{/link}ебальных Костров стояла крепость благородного барона {link:baron-silverlaine}Сильверлейн{/link}а. Когда король {link:genn-greymane}Генн Седогрив{/link} закрыл свое королевство после {link:second-war}Второй войны{/link}, поперек юга леса поднялась {link:the-greymane-wall}Стена Седогрива{/link}, и врата {link:gilneas}Гилнеас{/link}а затворились за ней. Жители Серебряного бора остались на северной стороне.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:sylvanas-windrunner}Темная Госпожа{/link} поручила своему наместнику {link:varimathras}Вариматасу{/link} взять земли на юге, и Серебряный бор — первый шаг. {link:high-executor-hadrec}Верховный исполнитель Хадрек{/link} командует Отрекшимися в Гробнице, но врагов у него много. {link:gnolls}Гноллы{/link} Гнилошкуры, которых поднял и подчинил маг-предатель {link:thule-ravenclaw}Туле Коготь Ворона{/link}, возят трупы из {link:tirisfal-glades}Тирисфаль{/link}ских лесов на {link:fenris-isle}Остров Фенриса{/link}. Воргены архимага {link:archmage-arugal}Аругал{/link}а рыщут по лесам, а жители Деревни П{link:ogres}огр{/link}ебальных Костров каждую ночь превращаются в зверей. В Янтарной мельнице {link:the-wizards-of-ambermill}волшебники Даларана{/link} трудятся над собственной тайной и тяжелой рукой стерегут дороги. У Стены {link:genn-greymane}Седогрив{/link}а перепуганные беженцы-люди собираются перед вратами, которые не откроются.

В эти дни паладины {link:tyr-s-watch}Дозора Тира{/link} прислали в Гробницу своего человека, а в лес пришла странница из народа {link:skyborne}Рожденных Небом{/link} и принесла с собой горе.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:forsaken}Отрекшиеся{/link}.{/b} Стражи смерти, ловчие смерти, аптекари и мертвый архимаг {link:dalaran}Даларан{/link}а — все они служат Темной Госпоже из Гробницы.
• {b}{link:scourge}Плеть{/link}.{/b} {link:gnolls}Гноллы{/link} Гнилошкуры, слуги мага {link:thule-ravenclaw}Туле{/link} Когтя Ворона и безмозглые мертвецы старых ферм.
• {b}Воргены.{/b} Стая Лунной Ярости и Сыновья архимага — одичавшие люди-волки, которые отчасти подчиняются архимагу Крепости Темного Клыка.
• {b}Проклятые Деревни П{link:ogres}огр{/link}ебальных Костров.{/b} Селяне, которые днем люди, а ночью звери.
• {b}{link:the-wizards-of-ambermill}Волшебники Янтарной мельницы{/link}.{/b} Маги ордена {link:kirin-tor}Кирин-Тор{/link} и их стража, не дружественные ни живым, ни мертвым севера.
• {b}Звери и мурлоки.{/b} Ворги, седые медведи, огромные пауки и {link:murlocs}мурлоки{/link} Мерзкого Плавника с берега озера.]=],
		},
		{
			title = "История",
			text = [=[• {b}Чума.{/b} В {link:third-war}Третью войну{/link} чума прокатилась по землям {link:lordaeron}Лордерон{/link}а. Фермеры севера Серебряного бора умерли на своей земле и восстали в рядах Плети.
• {b}Воргены.{/b} Волшебники {link:dalaran}Даларан{/link}а сражались с {link:scourge}Плеть{/link}ю в лесу, и их собственные мертвецы восставали против них. Вопреки совету собратьев архимаг {link:archmage-arugal}Аругал{/link} воззвал к силам из-за пределов мира, и пришли воргены. Они перебили мертвых, а затем обратились против волшебников. Они взяли крепость барона, и Аругал сделал ее своей.
• {b}{link:forsaken}Отрекшиеся{/link}.{/b} Со временем Отрекшиеся пришли на юг из {link:tirisfal-glades}Тирисфаль{/link}ских лесов и сделали Гробницу своим оплотом в лесу.]=],
		},
		{
			title = "Предания леса",
			text = [=[• Аптекари говорят, что века назад чума убила все живое в водах озера Лордамер.
• Трое молодых магов однажды сплели единый жезл из своих ученических жезлов в знак дружбы. Одним из них был {link:thule-ravenclaw}Туле Коготь Ворона{/link}.
• Мертвый архимаг в Гробнице утверждает, что {link:archmage-arugal}Аругал{/link} вовсе не обладал силой сотворить воргена.]=],
		},
	},
})

Translate("ruRU", "the-sepulcher", {
	title = "Гробница",
	aliases = { "Гробница Серебряного бора" },
	sections = {
		{
			title = "Обзор",
			text = [=[Гробница — оплот {link:forsaken}Отрекшихся{/link} в Серебряном бору. Она стоит на лесистом холме в сердце леса — старое кладбище, где мертвые теперь несут дозор над миром живых. Отсюда {link:high-executor-hadrec}Верховный исполнитель Хадрек{/link} рассылает своих ловчих смерти, а стражи смерти держат дороги. Мертвый архимаг изучает проклятие воргенов, жрец Тьмы собирает каждую крупицу вестей, а аптекарь Общества трудится над новой чумой. Нетопыри носят всадников на север, в {link:undercity}Подгород{/link}. В эти дни Гробница дает приют также посланнику {link:morgan-s-vigil}Дозор{/link}а Тира и молодой женщине из народа {link:skyborne}Рожденных Небом{/link}.]=],
		},
	},
})

Translate("ruRU", "pyrewood-village", {
	title = "Деревня Погребальных Костров",
	aliases = { "Погребальные Костры" },
	sections = {
		{
			title = "Обзор",
			text = [=[Деревня Погребальных Костров — маленькое селение на юге Серебряного бора, под стенами Крепости Темного Клыка. Днем она выглядит как любая другая людская деревушка: ратуша, трактир, кузнецы и портные за работой и {link:the-night-watch}дозорные{/link} на улицах. Когда заходит солнце, ее жители становятся воргенами. {link:archmage-arugal}Аругал{/link} наложил на всех них зачарованные оковы и правит деревней через ее собственный совет, члены которого — его марионетки. В трактире находится кабинет аптекаря, который пал жертвой того же проклятия. В ратуше прячется ловчий смерти, дожидаясь, когда совет вернется домой.]=],
		},
	},
})

Translate("ruRU", "ambermill", {
	title = "Янтарная мельница",
	sections = {
		{
			title = "Обзор",
			text = [=[Янтарная мельница — деревня в холмах на юго-востоке Серебряного бора, близ берега озера Лордамер. Она никогда не была важным местом. И все же маги {link:dalaran}Даларана{/link} наполнили ее волшебниками, заклинателями и вооруженными стражами и возят в нее на телегах из {link:hillsbrad-foothills}Предгорий Хилсбрада{/link} ящики с картами и руническими подвесками. {link:forsaken}Отрекшиеся{/link} полагают, что знают причину. Янтарная мельница лежит над спящим узлом силовых линий, и один архимаг трудится, чтобы его пробудить. Что {link:kirin-tor}Кирин-Тор{/link} намерен делать с такой силой, в Гробнице никто сказать не может.]=],
		},
	},
})

Translate("ruRU", "fenris-isle", {
	title = "Остров Фенриса",
	sections = {
		{
			title = "Обзор",
			text = [=[Остров Фенриса лежит на озере Лордамер, к востоку от Старой переправы. Это оплот {link:scourge}Плети{/link} в Серебряном бору. {link:gnolls}Гноллы{/link} Гнилошкуры кишат на его берегах и в его разрушенной крепости. Лодка перевозит трупы из {link:tirisfal-glades}Тирисфаль{/link}ских лесов через воду от переправы, и на острове эти трупы служат новому хозяину. На его пляжах охотятся {link:murlocs}мурлок{/link}и Мерзкого Плавника, а среди камышей ползают поросшие мхом озерные твари. С недавних пор стражи смерти видели, как гноллы бросили {link:ogres}огр{/link}омное тело на погребальный костер у берега. Это было тело {link:tauren}таурен{/link}а.]=],
		},
	},
})

Translate("ruRU", "fenris-keep", {
	title = "Крепость Фенриса",
	sections = {
		{
			title = "Обзор",
			text = [=[Крепость Фенриса — твердыня на Острове Фенриса. Там правит {link:thule-ravenclaw}Туле Коготь Ворона{/link} со своими {link:gnolls}гнолл{/link}ами Гнилошкурами. В ее дворе, близ старой конюшни, гноллы закопали обезглавленное тело в безымянной могиле. Голову они оставили себе как игрушку. Она все еще говорит. Аларик, главный слуга мага-предателя, провел в этой крепости лучшие дни своей жизни и знает ее тайны, среди которых — потайная ниша в юго-западной башне. С недавних пор гноллы держат в клетке внутри стен еще и живую пленницу.]=],
		},
	},
})

Translate("ruRU", "the-decrepit-ferry", {
	title = "Старая переправа",
	sections = {
		{
			title = "Обзор",
			text = [=[Старая переправа — старый причал на берегу озера Лордамер, к востоку от Гробницы. Она сгнила и почти забыта, но не пустует. Ее стерегут слуги мага {link:thule-ravenclaw}Туле{/link} Когтя Ворона, и {link:gnolls}гнолл{/link}ы Гнилошкуры приходят и уходят. В лодке, привязанной там, лежат груды тел, завернутых для перевозки. По ту сторону воды, на Острове Фенриса, стоит второй причал. {link:forsaken}Отрекшиеся{/link} узнали, что тела привозят из братских могил {link:tirisfal-glades}Тирисфаль{/link}ских лесов — среди них женщина из {link:brill}Брилл{/link}а по имени Делия — и что все они кончают свой путь на острове.]=],
		},
	},
})

Translate("ruRU", "the-dead-field", {
	title = "Мертвое поле",
	aliases = { "Мертвые поля" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мертвое поле — заброшенный хутор на севере Серебряного бора. {link:gnolls}Гноллы{/link} Гнилошкуры устроили в нем лагерь, и ловчие смерти, следившие за ним, думали, что гноллы готовятся к войне. {link:forsaken}Отрекшиеся{/link} нападали на них не раз, и каждый раз их обращала в бегство банши Ночная {link:scourge}Плеть{/link}, которая приходила гноллам на помощь со своей магией. {link:high-executor-hadrec}Хадрек{/link} хотел, чтобы ее уничтожили. Говорят, что когда Ночная Плеть гибнет, ее сущность обращается в прах.]=],
		},
	},
})

Translate("ruRU", "the-ivar-patch", {
	title = "Делянка Ивара",
	sections = {
		{
			title = "Обзор",
			text = [=[Делянка Ивара была фермой человека по имени {link:ivar-the-foul}Ивар{/link} на дальнем севере Серебряного бора. Когда пришла чума, Ивар, большая часть его семьи и его работники — все пали и восстали вновь в рядах {link:scourge}Плети{/link}. Ивар и поныне обитает в своем амбаре как вурдалак. Ловчие смерти {link:rane-yorick}Рейн{/link} и {link:quinn-yorick}Квинн Йорик{/link} попали здесь в засаду во время своего задания и сделали его старый дом своим убежищем. Из его окон Рейн несет дозор, пока Квинн залечивает раны наверху.]=],
		},
	},
})

Translate("ruRU", "malden-s-orchard", {
	title = "Сад Мальдена",
	sections = {
		{
			title = "Обзор",
			text = [=[Сад Мальдена лежит на дальнем северо-востоке Серебряного бора, близ границы {link:tirisfal-glades}Тирисфаль{/link}ских лесов. Его деревья стоят неубранными, а тот, кто жил в его домике, исчез. Теперь сад заполнили ворги, и их так много, что ловчий смерти, посланный его разведать, на несколько дней оказался заперт в домике. Ворги следили за дверью и ждали, когда он выйдет. Среди них охотится {link:ogres}огр{/link}омный черный ворг, известный как {link:warlord-goretooth}Кровавый Клык{/link}.]=],
		},
	},
})

Translate("ruRU", "valgan-s-field", {
	title = "Поле Валгана",
	sections = {
		{
			title = "Обзор",
			text = [=[Поле Валгана — пшеничная ферма на севере Серебряного бора, чуть севернее моста через небольшую реку. Когда архимаг {link:archmage-arugal}Аругал{/link} впервые пришел в лес, он остановился именно здесь. Он оставил после себя книги заклинаний, и ловчие смерти, нашедшие их, не смогли их унести. Среди них было заклинание, которое Аругал называл своим средством. Теперь по земле вокруг фермы бродят воргены.]=],
		},
	},
})

Translate("ruRU", "north-tide-s-hollow", {
