	sections = {
		{
			title = "Обзор",
			text = [=[Северная приливная низина — полоса леса чуть севернее Гробницы, в сторону западного моря. Воргены стаи Лунной Ярости сделали ее одним из своих логовищ. Их обжоры и темные души рыщут среди деревьев, и каждый носит зачарованные оковы, которые сделал {link:archmage-arugal}Аругал{/link}. Мертвый архимаг в Гробнице пристально изучил эти оковы. Они стали первым доказательством, говорит он, что магия их создателя слабее, чем верил мир.]=],
		},
	},
})

Translate("ruRU", "olsen-s-farthing", {
	title = "Удел Ольсена",
	sections = {
		{
			title = "Обзор",
			text = [=[Удел Ольсена — разоренный хутор у главной дороги, к югу от Гробницы. Некогда он торговал с каждой повозкой, проезжавшей через лес. Теперь ферму наводнили мертвецы. Там собрались налетчики и рабы на службе у мага {link:thule-ravenclaw}Туле{/link} Когтя Ворона, и они набрасываются на всякого, кто подойдет близко. Отрекшимся приходится проходить мимо них каждый раз, когда они идут южной дорогой.]=],
		},
	},
})

Translate("ruRU", "the-skittering-dark", {
	title = "Струящаяся Тьма",
	sections = {
		{
			title = "Обзор",
			text = [=[Струящаяся Тьма — затянутая паутиной лощина на северо-западе Серебряного бора, близ моря. Там гнездятся {link:ogres}огр{/link}омные мшистые охотники и туманные ползуны, а по ее краям бродят медведи. Аптекари Гробницы высоко ценят кровь ее пауков. Смешанная с ядом, добытым из сердца седого медведя, она дает смертоносный эликсир, и Общество надеется, что он станет шагом к новой чуме. Рыбак из Отрекшихся забрасывает удочку с ближнего берега, словно пауки его вовсе не заботят.]=],
		},
	},
})

Translate("ruRU", "deep-elem-mine", {
	title = "Серебряный рудник",
	sections = {
		{
			title = "Обзор",
			text = [=[Серебряный рудник лежит в холмах в середине Серебряного бора, к юго-востоку от Гробницы. Магия архимага дотянулась даже сюда, и ее жертвой стал сам штейгер рудника, {link:grimson-the-pale}Гримсон Бледный{/link}. Теперь туннели держат воргены стаи Лунной Ярости. {link:forsaken}Отрекшиеся{/link} хотят получить рудник для грядущей войны, ибо его руда питала бы поход, который {link:varimathras}Вариматас{/link} ведет на юг. {link:dalar-dawnweaver}Далар Ткач Рассвета{/link} полагает, что со смертью штейгера рудник будет принадлежать Темной Госпоже.]=],
		},
	},
})

Translate("ruRU", "beren-s-peril", {
	title = "Погибель Берена",
	sections = {
		{
			title = "Обзор",
			text = [=[Погибель Берена — пещера в холмах к юго-западу от Янтарной мельницы, недалеко от лагеря волшебников {link:dalaran}Даларан{/link}а. {link:forsaken}Отрекшиеся{/link} узнали от своих разведчиков, что там собралась шайка нежити. Чернорабочие и стражи на службе у мага {link:thule-ravenclaw}Туле{/link} Когтя Ворона готовили нападение на саму Гробницу. {link:shadow-priest-allister}Жрец Тьмы Аллистер{/link} не стал ждать, пока они выступят. Он послал в пещеру собственных агентов, чтобы ударить первым.]=],
		},
	},
})

Translate("ruRU", "gates-of-shadowfang-keep", {
	title = "Врата Крепости Темного Клыка",
	sections = {
		{
			title = "Обзор",
			text = [=[{link:shadowfang-keep}Крепость Темного Клыка{/link} поднимается на холме на юге Серебряного бора, чуть севернее Деревни П{link:ogres}огр{/link}ебальных Костров. Это была крепость барона {link:baron-silverlaine}Сильверлейн{/link}а, пока ее не взяли воргены и архимаг {link:archmage-arugal}Аругал{/link} не сделал ее своим домом. С дороги видны лишь ее темные стены. Отсюда по лесу расходятся Сыновья архимага — огромные воргены, которые служат ему как его дети. {link:forsaken}Отрекшиеся{/link} посылали внутрь ловчих смерти. Ни один из них не вернулся.]=],
		},
	},
})

Translate("ruRU", "the-greymane-wall", {
	title = "Стена Седогрива",
	sections = {
		{
			title = "Обзор",
			text = [=[Стена Седогрива проходит по южному краю Серебряного бора и отгораживает королевство {link:gilneas}Гилнеас{/link} от севера. Король {link:genn-greymane}Генн Седогрив{/link} возвел ее после {link:second-war}Второй войны{/link}, и с тех пор ее врата остаются закрытыми — даже когда пришла чума. Перед стеной люди, бежавшие с севера, разбили лагерь отчаявшихся. Многие больны. Среди них трудится слепой кузнец. Поблизости рыщут воргены и ворги, и {link:forsaken}Отрекшиеся{/link} боятся, что проклятие переходит на беженцев. Жители Гилнеаса ясно дали понять, что не пропустят никого.]=],
		},
	},
})

Translate("ruRU", "pyrewood-villagers", {
	title = "Жители Деревни Погребальных Костров",
	aliases = { "Совет Деревни Погребальных Костров", "проклятые Погребальных Костров" },
	sections = {
		{
			title = "Обзор",
			text = [=[Жители Деревни Погребальных Костров живут двумя жизнями. Днем они люди: {link:the-night-watch}дозорные{/link}, старейшины, кузнецы, портные и кожевники, занятые своим делом. Когда солнце садится, проклятие архимага {link:archmage-arugal}Аругал{/link}а берет верх, и они становятся воргенами стаи Лунной Ярости. Каждый из них носит зачарованные оковы, которые наложил на них Аругал.]=],
		},
		{
			title = "Совет",
			text = [=[Деревней все еще управляет ее совет — восемь советников во главе с лорд-мэром Моррисоном. {link:forsaken}Отрекшиеся{/link} полагают, что совет больше не хозяин самому себе. {link:archmage-arugal}Аругал{/link} пользуется ими как марионетками, чтобы держать зверей деревни в повиновении, пока его внимание занято Крепостью Темного Клыка. {link:deathstalker-faerleia}Ловчая смерти Фаэрлея{/link} надеялась, что со смертью совета воргены обратятся против самого архимага.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не говорит, помнят ли селяне днем то, что делают ночью. Не записано, когда проклятие пало на них впервые.]=],
		},
	},
})

Translate("ruRU", "the-wizards-of-ambermill", {
	title = "Волшебники Янтарной мельницы",
	aliases = { "волшебники Даларана", "Кирин-Тор Янтарной мельницы" },
	sections = {
		{
			title = "Обзор",
			text = [=[Волшебники Янтарной мельницы — это маги {link:dalaran}Даларана{/link} и слуги, которые их охраняют: ученики, заклинатели, маги, {link:the-night-watch}дозорные{/link}, стражи и защитники, даже пивовар и рудокоп. Они подчиняются ордену {link:kirin-tor}Кирин-Тор{/link} и превратили сонную деревню Серебряного бора в собственную крепость.]=],
		},
		{
			title = "Их труд",
			text = [=[{link:ambermill}Янтарная мельница{/link} стоит на узле силовых линий, который долго дремал. {link:kirin-tor}Кирин-Тор{/link} выбрал ее именно поэтому, и архимаг ордена, {link:archmage-ataeric}Атаэрик{/link}, сплетает ее энергии, пробуждая их ради некой великой цели. Рунические подвески, которые они носят, — старые орудия ордена Кирин-Тор, служащие, чтобы направлять такую силу. Волшебники держат также лагерь к северу от Деревни П{link:ogres}огр{/link}ебальных Костров, куда приходят их ящики из Предгорий {link:hillsbrad-foothills}Хилсбрад{/link}а.]=],
		},
		{
			title = "Между живыми и мертвыми",
			text = [=[Для Отрекшихся {link:ambermill}Янтарная мельница{/link} — сердце сопротивления людей в лесу. Волшебники стоят на страже на дорогах с тех самых пор, как пал великий барьер {link:dalaran}Даларан{/link}а, и никого не пропускают свободно. Чего бы они ни боялись, они об этом не говорят.]=],
		},
	},
})

Translate("ruRU", "dalar-dawnweaver", {
	title = "Далар Ткач Рассвета",
	subtitle = "Архимаг Отрекшихся",
	found = "Гробница",
	hint = [=[Поговорите с мертвым архимагом, который изучает в Гробнице проклятие воргенов.]=],
	allegiance = "Отрекшиеся · прежде Кирин-Тор",
	aliases = { "Далар" },
	sections = {
		{
			title = "Обзор",
			text = [=[Далар Ткач Рассвета при жизни был архимагом {link:dalaran}Даларана{/link}. Однажды он предостерег орден {link:kirin-tor}Кирин-Тор{/link}, и его не послушали. Теперь он служит Темной Госпоже в Гробнице. К бывшему собрату {link:archmage-arugal}Аругал{/link}у он питает открытое презрение. Он называет того шарлатаном, который подпирал слабые заклинания зачарованными безделушками и никогда не должен был говорить от имени ордена Кирин-Тор.]=],
		},
		{
			title = "Значение",
			text = [=[Далар — знаток проклятия воргенов среди Отрекшихся. Недавно он пришел к смелому выводу: {link:archmage-arugal}Аругал{/link} мог сковывать зверей, но никогда их не создавал, и проклятие распространяется каким-то иным путем.]=],
		},
	},
	chapters = {
		{
			title = "Разоблаченный обман",
			hint = [=[Принесите мертвому архимагу доказательство от Стены Седогрива.]=],
			text = [=[Далар перебирал оковы, книги заклинаний и останки зверей, пока не убедился окончательно. Знаменитое проклятие было слишком немощным, чтобы продержаться дольше нескольких мгновений. Далар рассмеялся, ибо показал, что прославленный архимаг — обманщик. Потом он увидел цену: средство тоже ничего не стоило.]=],
		},
	},
	mentions = {
		{ text = "Докажи, чего ты стоишь" },
		{ text = "Безрассудство архимага: средство" },
		{ text = "Безрассудство архимага: оковы" },
		{ text = "Безрассудство архимага: рудник" },
		{
			text = [=[Безрассудство архимага: {link:pyrewood-village}Деревня Погребальных Костров{/link}]=],
		},
		{ text = "Остановить заразу" },
		{ text = "Замыслы {link:dalaran}Даларан{/link}а" },
		{ text = "{link:archmage-arugal}Аругал{/link} должен умереть" },
	},
	bonds = {
		{ id = "archmage-arugal", name = "Архимаг Аругал", note = "глупец, которого он презирает" },
		{ id = "shadow-priest-allister", name = "Жрец Тьмы Аллистер", note = "вместе с ним следит за Янтарной мельницей" },
	},
})

