Translate("ruRU", "apothecary-renferrel", {
	title = "Аптекарь Ренферрел",
	subtitle = "Аптекарь Гробницы",
	found = "Перед Гробницей",
	hint = "Найдите аптекаря Общества, который трудится перед Гробницей.",
	allegiance = "Королевское фармацевтическое общество",
	aliases = { "Ренферрел" },
	sections = {
		{
			title = "Обзор",
			text = [=[Аптекарь Ренферрел служит {link:royal-apothecary-society}Королевскому фармацевтическому обществу{/link} в Гробнице. Он верит, что новая чума могла бы уничтожить армии, которые ведет {link:arthas-menethil}Артас{/link}, и людей вместе с ними, и трудится над ней без отдыха. У него мало терпения к тем, кто его прерывает, и еще меньше — к тем, кто сомневается в его рецептах.]=],
		},
