Translate("ruRU", "genn-greymane", {
	title = "Генн Седогрив",
	subtitle = "Король Гилнеаса",
	found = "За Стеной Седогрива, в королевстве Гилнеас",
	hint = "Узнайте о короле, чья стена закрывает юг Серебряного бора.",
	allegiance = "Королевство Гилнеас",
	aliases = { "Седогрив", "король Седогрив", "король Генн Седогрив" },
	sections = {
		{
			title = "Обзор",
			text = [=[Генн Седогрив — король {link:gilneas}Гилнеаса{/link}. Это гордый и упрямый правитель, воин, который доверяет своему народу и мало кому еще. Именно он вывел свое королевство из {link:alliance}Альянса{/link} после {link:second-war}Второй войны{/link}, и именно он возвел великую стену поперек юга Серебряного бора. За этой стеной его королевство жило своим умом, пока север лежал в руинах.]=],
		},
		{
			title = "Значение",
			text = [=[Седогрив — властитель, который решил стоять один. Его стена избавила его страну от цены чужих войн. Она же оставила север лицом к лицу с {link:scourge}Плетью{/link} без его армии. Спасла ли стена его королевство или лишь спрятала его, никто снаружи сказать не может.]=],
		},
		{
			title = "Деяния",
			text = [=[• Когда пал {link:stormwind-city}Штормград{/link}, он вместе с другими правителями людей прибыл на совет в столице {link:lordaeron}Лордерон{/link}а, созванный королем {link:terenas-menethil}Теренасом{/link}. Он сомневался в опасности и хвалился, что его армия встретит любую угрозу.
• Он вступил в {link:alliance}Альянс Лордерона{/link} неохотно и дал ему гораздо меньше, чем могло бы дать его государство.
• После войны он спорил с другими королями о цене лагерей для пленных {link:orcs}орк{/link}ов и Крепости Стражей Пустоты. Когда он пожаловался на расходы на эту крепость, молодой король {link:varian-wrynn}Вариан Ринн{/link} ответил, что их безопасности нельзя назначить цену.
• Он искал своей доли в судьбе {link:alterac-mountains}Альтерак{/link}а, оставшегося без правителя, и поддержал претендента на его трон.
• Он вывел свое королевство из Альянса, построил Стену Седогрива и закрыл ее врата.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[С тех пор как закрылись врата, из {link:gilneas}Гилнеас{/link}а не пришло ни слова. Что король Седогрив знает о воргенах у своих дверей и что происходит в его королевстве, ни одна летопись этих дней сказать не может.]=],
		},
	},
	chapters = {
		{
			title = "Стена его имени",
			hint = "Встаньте перед стеной, которая носит имя короля.",
			text = [=[Седогрив считал, что его страна ничего не должна войнам чужих государств. Когда {link:alliance}Альянс{/link} попросил его народ платить за лагеря для пленных {link:orcs}орк{/link}ов, он отказался и вовсе вывел свое королевство из Альянса. Потом он отгородил его стеной. {link:the-greymane-wall}Стена Седогрива{/link} поднялась вдоль северной границы {link:gilneas}Гилнеас{/link}а. Когда в земли {link:lordaeron}Лордерон{/link}а пришла чума, ее врата остались закрытыми. Ни одна армия из-за стены не пошла на север помогать гибнущему королевству.]=],
		},
		{
